python3 -c "
import yaml, re

with open('literature_map.yaml', 'r') as f:
    data = yaml.safe_load(f)

# Venue classification
article_venues = {'nature', 'jmlr', 'pattern recognition letters', 'tacl'}
conf_keywords = ['icml', 'iclr', 'neurips', 'emnlp', 'acl', 'coling', 'cvpr', 'icassp']

# Venue to booktitle/journal mapping
venue_map = {
    'nature': ('article', 'Nature'),
    'jmlr': ('article', 'Journal of Machine Learning Research'),
    'pattern recognition letters': ('article', 'Pattern Recognition Letters'),
    'tacl': ('article', 'Transactions of the Association for Computational Linguistics'),
}

def classify_venue(venue):
    vl = venue.lower()
    if 'arxiv' in vl or 'preprint' in vl:
        return 'misc', None
    for k, v in venue_map.items():
        if k in vl:
            return v
    for kw in conf_keywords:
        if kw in vl:
            # Determine booktitle
            if 'findings' in vl:
                conf = kw.upper()
                return 'inproceedings', f'Findings of {conf}'
            else:
                conf = kw.upper()
                # Handle TMLR dual venue
                if '/' in venue:
                    conf = venue.split('/')[0].strip()
                    conf = re.sub(r'\s*\d{4}.*', '', conf)
                return 'inproceedings', f'Proceedings of {conf}'
    return 'misc', None

def format_authors(authors_list):
    parts = []
    for a in authors_list:
        a = str(a).strip()
        if a.lower() in ('et al.', 'et al'):
            parts.append('others')
        elif ' ' in a and not a.startswith('('):
            parts.append('{' + a + '}')
        else:
            parts.append(a)
    return ' and '.join(parts)

entries = []
for key, val in data.items():
    if not isinstance(val, dict) or 'title' not in val:
        continue

    venue = val.get('venue', '')
    entry_type, venue_name = classify_venue(venue)

    authors = format_authors(val.get('authors', []))
    title = val['title']
    year = val.get('year', '')
    arxiv = val.get('arxiv', '')
    doi = val.get('doi', '')

    lines = [f'@{entry_type}{{{key},']
    lines.append(f'  author    = {{{authors}}},')
    lines.append(f'  title     = {{{{{title}}}}},')

    if entry_type == 'article':
        lines.append(f'  journal   = {{{venue_name}}},')
    elif entry_type == 'inproceedings':
        lines.append(f'  booktitle = {{{venue_name}}},')

    lines.append(f'  year      = {{{year}}},')

    if doi:
        lines.append(f'  doi       = {{{doi}}},')

    if arxiv:
        if entry_type == 'misc':
            lines.append(f'  howpublished = {{arXiv:{arxiv}}},')
        else:
            lines.append(f'  note      = {{arXiv:{arxiv}}},')

    lines.append('}')
    entries.append('\n'.join(lines))

output = '\n\n'.join(entries) + '\n'
print(f'Total entries: {len(entries)}')

with open('docs/paper/references.bib', 'w') as f:
    f.write(output)
print('Written to docs/paper/references.bib')
"
